// Host adapter for the former private signed_head formatting block. Its
// structured fields supply the already prepared method/path/header borrows.
pub struct RequestHead<'a> {
 pub method: &'a str, pub path: &'a str,
 pub headers: &'a [crate::sigv4::Header<'a>], pub content_length: Option<u64>,
}
pub fn request_head(request: &RequestHead<'_>) -> Result<Vec<u8>,Error> {
 use core::fmt::Write;
 use alloc::string::String;
 let value=|name:&str| request.headers.iter().find(|h| h.name.eq_ignore_ascii_case(name)).map(|h|h.value);
 let mut output=String::new();
 let _=write!(output,"{} {} HTTP/1.1\r\nHost: {}\r\nx-amz-content-sha256: {}\r\nx-amz-date: {}\r\nAuthorization: {}\r\n",request.method,request.path,value("Host").unwrap_or(""),value("x-amz-content-sha256").unwrap_or(""),value("x-amz-date").unwrap_or(""),value("Authorization").unwrap_or(""));
 if let Some(namespace)=value("x-emc-namespace") { let _=write!(output,"x-emc-namespace: {}\r\n",namespace); }
 if let Some(range)=value("Range") { let _=write!(output,"Range: {}\r\n",range); }
 if value("If-None-Match").is_some() { output.push_str("If-None-Match: *\r\n"); }
 if let Some(length)=request.content_length { let _=write!(output,"Content-Length: {}\r\n",length); }
 output.push_str("Connection: close\r\n\r\n");
 Ok(output.into_bytes())
}

